-- RLS tests for public.calendar_feed_tokens
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
create function pg_temp.n(q text) returns int language plpgsql as $f$ declare c int; begin execute q; get diagnostics c = row_count; return c; end $f$;

update public.profiles set display_name = 'Pat Ava' where id = 'a2222222-2222-2222-2222-222222222222';
-- Team A (club-linked, soccer): admin, coach, parents Ava/Ben, player Teen. Team B (basketball): coach B, parent Other.
-- Active on A: Ava, Ben, Teen. Inactive on A: Dan. Active on B: Cleo, Ivy (Ava's second team).

reset role;
reset role; set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select id from public.calendar_feed_tokens $$, '42501', null, 'anonymous users cannot read feed tokens');
reset role; select set_config('request.jwt.claims', '{"sub":"a2222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from (select id, profile_id, created_at, revoked_at, last_used_at from public.calendar_feed_tokens) x), 1, 'a user reads only their own token rows');
select throws_ok($$ select token_hash from public.calendar_feed_tokens $$, '42501', null, 'the token hash column is not readable by clients');
select throws_ok($$ insert into public.calendar_feed_tokens (profile_id, token_hash) values ('a2222222-2222-2222-2222-222222222222', repeat('c', 64)) $$, '42501', null, 'clients cannot insert tokens directly');
select throws_ok($$ update public.calendar_feed_tokens set revoked_at = null $$, '42501', null, 'clients cannot update tokens directly');
select throws_ok($$ delete from public.calendar_feed_tokens $$, '42501', null, 'clients cannot delete tokens directly');
reset role; select set_config('request.jwt.claims', '{"sub":"a1111111-1111-1111-1111-111111111111","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from (select id from public.calendar_feed_tokens) x), 0, 'staff cannot read other people''s tokens');
reset role;
select throws_ok($$ insert into public.calendar_feed_tokens (profile_id, token_hash) values ('a2222222-2222-2222-2222-222222222222', repeat('d', 64)) $$, '23505', null, 'only one live token per person');
select throws_ok($$ insert into public.calendar_feed_tokens (profile_id, token_hash) values ('a1111111-1111-1111-1111-111111111111', 'not-a-hash') $$, '23514', null, 'token_hash must look like a SHA-256 hex digest');
update public.calendar_feed_tokens set revoked_at = now() where profile_id = 'a2222222-2222-2222-2222-222222222222';
select lives_ok($$ insert into public.calendar_feed_tokens (profile_id, token_hash) values ('a2222222-2222-2222-2222-222222222222', repeat('d', 64)) $$, 'a new token is allowed once the old one is revoked');
select * from finish();
rollback;
